                R(ref s, "All mention of that which has been discussed in this\r\ncourtroom today <E049><E003 10><E025 3>will be struck from the records.", "Toute mention de ce qui a été débattu dans ce prétoire\r\naujourd'hui <E049><E003 10><E025 3>sera effacée des registres.");
                R(ref s, "Barok van Zieks –<E049><E003 10> or should I say, <E049><E003 8>Reaper of the Bailey...", "Barok Van Peers –<E049><E003 10> ou devrais-je dire, <E049><E003 8>Faucheur de la Cour...");
                R(ref s, "...the heinous crimes committed by your brother,<E049><E003 6> Klint\r\nvan Zieks, <E049><E003 8>will be lost in obscurity, <E049><E003 8><E025 3>this time forever.", "...les forfaits abominables perpétrés par votre frère,<E049><E003 6> Klint\r\nVan Peers, <E049><E003 8>sombreront dans l'oubli, <E049><E003 8><E025 3>cette fois à jamais.");
                R(ref s, "May you also find peace now <E049><E003 8>as you join your sibling in\r\nthe eternal darkness.", "Puissiez-vous trouver la paix à présent <E049><E003 8>en rejoignant votre frère\r\ndans les ténèbres éternelles.");
                R(ref s, "So...", "Ainsi...");
                R(ref s, "In accordance with the findings of this court, <E049><E003 8>I hereby\r\npronounce the defendant, <E049><E003 8><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 8>je déclare\r\npar la présente l'accusé, <E049><E003 8><E025 3>Barok Van Peers...");
                R(ref s, "Court is adjourned!", "La séance est levée !");
                return s;
            };

            // [137] BB\script\output\_sce04_c404_0030_eng#2
            entryTranslators[@"BB\script\output\_sce04_c404_0030_eng#2"] = (s) => {
                R(ref s, "What on earth is all this about?!", "Mais que signifie tout ce tapage ?!");
                R(ref s, "Buckingham Palace<E049><E003 3> <E164 9 87 1 2 6 0 1 1><E139 9>is Her Majesty the Queen's residence\r\nin London, <E049><E003 6>Mr Naruhodo!", "Le palais de Buckingham<E049><E003 3> <E164 9 87 1 2 6 0 1 1><E139 9>est la résidence londonienne de Sa Majesté la Reine,\r\n<E049><E003 6>Monsieur Naruhodo !");
                R(ref s, "Order!<E049><E003 5> Order in court!<E049><E003 12>\r\n<E346><E342>I demand immediate silence!", "Silence !<E049><E003 5> Silence dans ce tribunal !<E049><E003 12>\r\n<E346><E342>J'exige le calme immédiat !");
                R(ref s, "Her, <E049><E003 10><E342>Her Majesty the Queen?<E003 14>\r\n<E603><E025 2>You can't be...?<E003 12> I mean...<E003 12> No...", "Sa... <E049><E003 10><E342>Sa Majesté la Reine ?<E003 14>\r\n<E603><E025 2>Vous ne pouvez pas... ?<E003 12> C'est-à-dire... <E003 12>Non...");
                R(ref s, "This,<E049><E003 10> <E046>this is some sort of unforgivably distasteful trickery\r\nby a third-rate detective,<E049><E003 10> <E025 1>that's all!", "Ce n'est...<E049><E003 10> <E046>ce n'est qu'une grossière et impardonnable supercherie\r\nd'un détective de pacotille,<E049><E003 10> <E025 1>rien de plus !");
                R(ref s, "‘Unforgivably distasteful trickery’...<E049><E003 14>\r\n<E025 2>What an apt description.", "« Grossière et impardonnable supercherie »...<E049><E003 14>\r\n<E025 2>Quelle description on ne peut plus judicieuse.");
                R(ref s, "A closed court session attended by elite members of the\r\njudiciary is a rare event.", "Une audience à huis clos réunissant le gratin de la magistrature\r\nest un événement rarissime.");
                R(ref s, "I presumed that Her Majesty would be more than a little\r\ncurious about the proceedings.", "J'ai présumé que Sa Majesté serait au plus haut point curieuse\r\nd'en suivre les péripéties.");
                R(ref s, "So...<E049><E003 10><E025 2><E333>I decided to show her.<E049><E003 7><E145 2 64><E118 2 1.1><E003 20>\r\n<E330><E025 3>Everything...<E003 12>from start to finish.", "Dès lors... <E049><E003 10><E025 2><E333>j'ai résolu de tout lui montrer.<E049><E003 7><E145 2 64><E118 2 1.1><E003 20>\r\n<E330><E025 3>Absolument tout... <E003 12>du début jusqu'à la fin.");
                R(ref s, "Huh?!<E049><E003 16>\r\n<E338><E341><E025 2>You <E006>showed her<E005>?", "Hein ?!<E049><E003 16>\r\n<E338><E341><E025 2>Vous lui avez <E006>montré<E005> ?");
                R(ref s, "Indeed.", "Tout à fait.");
                R(ref s, "By dint of the Herlock Sholmes <E006>Remote Cinematograph<E005>!", "Par le truchement du <E006>Cinématographe à Distance<E005> de Herlock Sholmes !");
                R(ref s, "You...<E049><E003 14><E025 3><E342><E338>meddling...", "Espèce... <E049><E003 14><E025 3><E342><E338>d'insupportable fouineur...");
                R(ref s, "This is <E049><E003 8><E342><E338>some kind of nightmare...", "C'est <E049><E003 8><E342><E338>un pur cauchemar éveillé...");
                R(ref s, "Just as I appear to be standing before you,<E049><E003 8> regaling you\r\nwith talk of my latest invention...", "Tout comme j'ai l'honneur d'apparaître devant vous,<E049><E003 8> vous régalant\r\ndu récit de ma dernière trouvaille...");
                R(ref s, "...no doubt you've inferred...<E049><E003 8><E145 2 83><E117 2 20><E003 15><E330><E025 3>that <E006>the reverse<E005> is also true.", "...vous aurez sans nul doute déduit...<E049><E003 8><E145 2 83><E117 2 20><E003 15><E330><E025 3>que <E006>l'inverse<E005> s'applique tout autant.");
                R(ref s, "You, <E049><E003 10><E338><E342>you don't mean...?", "Vous... <E049><E003 10><E338><E342>ne me dites pas que... ?");
                R(ref s, "Her Majesty has seen and heard every moment of the\r\nproceedings.", "Sa Majesté n'a rien manqué, voyant et entendant chaque instant\r\nde ces débats.");
                R(ref s, "I assumed there would be no objection.<E049><E003 12>\r\n<E025 3>After all...", "J'ai présumé que personne n'y trouverait à redire.<E049><E003 12>\r\n<E025 3>Après tout...");
                R(ref s, "...every trial in this country <E049><E003 10><E164 2 70 1 2 8 0 2 1><E118 2 1.1><E139 2><E025 1>is conducted under the\r\nauspices of Her Majesty, <E049><E003 8>as you know!", "...tout procès en ce royaume <E049><E003 10><E164 2 70 1 2 8 0 2 1><E118 2 1.1><E139 2><E025 1>est rendu sous les\r\nauspices bienveillants de Sa Majesté, <E049><E003 8>comme vous le savez !");
                R(ref s, "You<E025 7>...<E003 14> <E025 3><E342><E339>You<E025 7>...", "Vous...<E003 14> <E025 3><E342><E339>Vous...");
                R(ref s, "I confess, <E049><E003 8>I am quite impatient to hear Her Majesty's\r\nopinion...", "J'avoue que je brûle d'impatience de connaître l'avis de Sa Majesté...");
                R(ref s, "...about the ‘unforgivably distasteful trickery’ in which\r\nyou've been engaged over the past ten years.", "...sur les « grossières et impardonnables supercheries » auxquelles\r\nvous vous livrez depuis dix ans.");
                R(ref s, "N-<E049><E003 8><E025 1>No!<E049><E003 12>\r\n<E025 2><E342>I, <E049><E003 10><E045>I was merely<E341>...", "N-<E049><E003 8><E025 1>Non !<E049><E003 12>\r\n<E025 2><E342>Je... <E049><E003 10><E045>je n'ai fait que...");
                R(ref s, "Oh, <E049><E003 8><E025 1>so sorry to keep you all waiting!<E049><E003 8><E145 4 65><E118 4 1.15><E003 6>\r\n<E025 2>Vicky and I had so much to talk about!", "Oh, <E049><E003 8><E025 1>navrée de vous avoir fait attendre !<E049><E003 8><E145 4 65><E118 4 1.15><E003 6>\r\n<E025 2>Vicky et moi avions tellement de choses à nous dire !");
                R(ref s, "Iris!<E049><E003 8> <E164 9 87 1 2 8 0 3 1><E118 9 1.2><E139 9><E025 1>There <E145 1 2>you are!", "Iris !<E049><E003 8> <E164 9 87 1 2 8 0 3 1><E118 9 1.2><E139 9><E025 1>Te voilà <E145 1 2>enfin !");
                R(ref s, "In fact, <E049><E003 8><E025 2>I have a little <E006>message<E005> here from Her Majesty.", "D'ailleurs, <E049><E003 8><E025 2>j'ai ici un petit <E006>message<E005> de la part de Sa Majesté.");
                R(ref s, "A, <E049><E003 12><E025 3><E338><E341>a message...?", "Un... <E049><E003 12><E025 3><E338><E341>un message... ?");
                R(ref s, "Well then, <E049><E003 10><E025 2>if everyone is sitting comfortably?<E049><E003 15>\r\n<E025 3>Ahem...", "Bien, <E049><E003 10><E025 2>tout le monde est-il bien installé ?<E049><E003 15>\r\n<E025 3>Hum, hum...");
                R(ref s, "‘Forthwith and with immediate effect, <E049><E003 12>all authority\r\npreviously afforded to Mael Stronghart...’", "« Dès à présent et avec effet immédiat, <E049><E003 12>toute l'autorité\r\nconférée jusqu'alors à Mael Stronghart... »");
                R(ref s, "‘...is hereby revoked for evermore.’", "« ...est par la présente révoquée à perpétuité. »");
                R(ref s, "...Ah...", "...Ah...");
                R(ref s, "‘Furthermore, <E049><E003 10>he will be prosecuted for crimes against\r\nhis country in a public trial by jury in the coming days.’", "« En outre, <E049><E003 10>il sera poursuivi pour crimes contre la nation\r\nlors d'un procès public devant jury populaire dans les jours à venir. »");
                R(ref s, "So...<E049><E003 14><E149 112 0 4><E025 3><E238>it seems that Her Majesty doesn't believe we need to\r\nfight fire with fire.", "Ainsi... <E049><E003 14><E149 112 0 4><E025 3><E238>il semble que Sa Majesté ne partage point l'idée qu'il faille\r\ncombattre le mal par le mal.");
                R(ref s, "Justice in this country <E049><E003 8>needn't be administered from the\r\nshadows at all.", "La justice de ce pays <E049><E003 8>n'a nul besoin d'être administrée depuis\r\nles ténèbres.");
                R(ref s, "Mael Stronghart...", "Mael Stronghart...");
                R(ref s, "...the darkness you fostered to conceal your despicable\r\nactions these last ten years <E049><E003 10><E025 3>is a thing of the past now.", "...les ombres que vous avez entretenues pour masquer vos infamies\r\nces dix dernières années <E049><E003 10><E025 3>appartiennent désormais au passé.");
                R(ref s, "After today...", "Après ce jour...");
                R(ref s, "...your brand of ‘law and order’ has no future.<E049><E003 12>\r\n<E025 3>Because no longer are you the Lord Chief Justice...", "...votre vision de « la loi et l'ordre » n'a plus d'avenir.<E049><E003 12>\r\n<E025 3>Car vous n'êtes plus le Lord juge en chef...");
                R(ref s, "In the eyes of the law, <E049><E003 8>and of Her Majesty the Queen...<E049><E003 16><E549 7 19 3 1><E003 3>\r\n<E607><E339>you are nothing...<E003 18><E025 1><E341><E338>but a criminal!", "Aux yeux de la loi, <E049><E003 8>et aux yeux de Sa Majesté la Reine...<E049><E003 16><E549 7 19 3 1><E003 3>\r\n<E607><E339>vous n'êtes rien d'autre... <E003 18><E025 1><E341><E338>qu'un criminel !");
                R(ref s, "Adjourned!<E003 32> <E332><E025 1><E342>Adjourned!<E003 24> <E332><E025 1><E342>Adjourned!<E003 18> <E332><E025 1><E342>Adjourned!<E003 22>\r\n<E332><E025 1><E342>Adjourned!", "Levée !<E003 32> <E332><E025 1><E342>Levée !<E003 24> <E332><E025 1><E342>Levée !<E003 18> <E332><E025 1><E342>Levée !<E003 22>\r\n<E332><E025 1><E342>Levée !");
                R(ref s, "COURT IS ADJOO<E343>OO<E338>OOOOOOOOOOOOOOOO<E342>OOOO\r\nUUUUUUU<E343>UUUUUUUU<E339>UUUUUUUUUU<E342>UUUUUURNED<E339>!!!", "LA SÉANCE EST LEEEE<E343>EE<E338>EEEEEEEEEEEEEEEE<E342>EEEE\r\nVÉÉÉÉÉÉÉ<E343>ÉÉÉÉÉÉÉÉ<E339>ÉÉÉÉÉÉÉÉÉÉ<E342>ÉÉÉÉÉÉE<E339> !!!");
                R(ref s, "AAAAAAAAAAAAAA<E343>AA<E338>AAAAAAAAAAAAAAAA<E342>AAAA\r\nAAAAAA<E343>AAAAAA<E339>AAAAAAAAAAA<E342>AAAAAAAAAA<E339>AGH!", "AAAAAAAAAAAAAA<E343>AA<E338>AAAAAAAAAAAAAAAA<E342>AAAA\r\nAAAAAA<E343>AAAAAA<E339>AAAAAAAAAAA<E342>AAAAAAAAAA<E339>AGH !");
                return s;
            };

