            // [139] BB\script\output\_sce04_c404_0040_eng#2
            entryTranslators[@"BB\script\output\_sce04_c404_0040_eng#2"] = (s) => {
                R(ref s, "‘Lord Klint van Zieks left a will in which he confessed to\r\neverything.’", "« Lord Klint Van Peers a laissé un testament dans lequel il avouait\r\ntout. »");
                R(ref s, "When those words came out of Asogi's mouth...<E049><E003 14>\r\n<E025 3>it deranged me completely.", "Lorsque ces mots ont franchi les lèvres d'Asogi...<E049><E003 14>\r\n<E025 3>j'ai perdu toute contenance.");
                R(ref s, "I knew I must do anything and everything in my power <E049><E003 14><E145 61 110><E118 61 0.5><E003 6>\r\n<E025 3>to contain the situation.", "J'ai su qu'il me fallait remuer ciel et terre <E049><E003 14><E145 61 110><E118 61 0.5><E003 6>\r\n<E025 3>pour étouffer l'affaire.");
                R(ref s, "But I couldn't find the damned document.<E049><E003 14>\r\n<E025 3>I searched his cell, <E049><E003 8>but it wasn't there.", "Mais ce maudit document restait introuvable.<E049><E003 14>\r\n<E025 3>J'ai fouillé sa cellule de fond en comble, <E049><E003 8>en vain.");
                R(ref s, "Which <E145 2 64><E118 2 1.15>precipitated the jailbreak plot, <E049><E003 6>I presume?", "Ce qui <E145 2 64><E118 2 1.15>a précipité le complot de l'évasion, <E049><E003 6>je présume ?");
                R(ref s, "W-<E049><E003 8>What do you mean?", "Q-<E049><E003 8>Que voulez-vous dire ?");
                R(ref s, "The need to obtain that will was all-consuming.", "L'obsession de récupérer ce testament me consumait tout entier.");
                R(ref s, "I was sure that if I facilitated Asogi's escape, <E049><E003 10><E025 3>he would\r\nemerge with the will somewhere on his person.", "J'étais convaincu qu'en facilitant l'évasion d'Asogi, <E049><E003 10><E025 3>il sortirait\r\navec le document caché sur lui.");
                R(ref s, "But despite searching his limp body in the cemetery that\r\nnight...<E003 14><E025 3>it still eluded me.", "Pourtant, malgré la fouille minutieuse de sa dépouille au cimetière\r\ncette nuit-là... <E003 14><E025 3>je ne pus mettre la main dessus.");
                R(ref s, "It never even crossed my mind <E049><E003 20><E092 6><E145 61 110><E118 61 0.4><E003 25><E239><E025 3>that it was concealed in\r\nthe sword's hilt.", "Il ne m'a jamais effleuré l'esprit <E049><E003 20><E092 6><E145 61 110><E118 61 0.4><E003 25><E239><E025 3>qu'il pût être dissimulé\r\ndans la garde même de son sabre.");
                R(ref s, "What pains me now...", "Ce qui m'accable aujourd'hui...");
                R(ref s, "...is that my brother left this world without a word to me.", "...c'est que mon frère ait quitté ce monde sans m'adresser un mot.");
                R(ref s, "I'm sorry, <E049><E003 8>Lord van Zieks...", "Je suis navré, <E049><E003 8>Lord Van Peers...");
                R(ref s, "In point of fact...", "En vérité...");
                R(ref s, "...I think perhaps that isn't the case.", "...je crois qu'il n'en est rien.");
                R(ref s, "Sorry?", "Pardon ?");
                R(ref s, "How can that be?", "Comment cela se pourrait-il ?");
                R(ref s, "There is <E006>more<E005> <E049><E003 8><E145 9 65><E149 9 0 4><E003 15><E025 3><E330>to his last will and testament.", "Ce testament <E049><E003 8><E145 9 65><E149 9 0 4><E003 15><E025 3><E330>comporte <E006>une suite<E005>.");
                R(ref s, "What?", "Quoi ?");
                R(ref s, "‘As I confront the prospect of my demise...<E003 15>\r\n<E042><CNTR>I feel bitter regret for my younger brother.’", "« À l'heure où j'envisage ma fin prochaine...<E003 15>\r\n<E042><CNTR>une amère culpabilité m'étreint à l'égard de mon jeune frère. »");
                R(ref s, "‘Barok, <E049><E003 16><E025 3>you have always looked up to me, <E003 10>and now,<E003 12>\r\n<E042><CNTR>you follow in my footsteps to become a prosecutor.’", "« Barok, <E049><E003 16><E025 3>tu m'as toujours voué une admiration sans borne, <E003 10>et voici qu'<E003 12>\r\n<E042><CNTR>à présent tu marches dans mes pas pour devenir procureur. »");
                R(ref s, "‘It is my fervent wish <E003 8>that my unspeakable\r\n<E042><CNTR>deeds should not hinder your advancement.’", "« C'est mon vœu le plus cher <E003 8>que mes forfaits\r\n<E042><CNTR>innommables n'entravent jamais ta brillante carrière. »");
                R(ref s, "‘I ask not for understanding, <E003 10>for none could\r\n<E042><CNTR>understand my depravity.<E003 15> <E025 3>I ask only for forgiveness.’", "« Je n'implore point ta compréhension, <E003 10>nul ne saurait\r\n<E042><CNTR>comprendre ma déchéance.<E003 15> <E025 3>Je n'implore que ton pardon. »");
                R(ref s, "‘Asogi is a fine detective, <E049><E003 8>and a hunter worthy of respect.’", "« Asogi est un brillant détective, <E049><E003 8>et un traqueur digne du plus grand respect. »");
                R(ref s, "‘He has agreed to honour my final two wishes.’", "« Il a consenti à honorer mes deux dernières volontés. »");
                R(ref s, "‘The first is that this document survives.<E049><E003 15>\r\n<E025 3>The second...<E049><E003 15><E025 3>I cannot commit to paper.’", "« La première est que cet écrit survive.<E049><E003 15>\r\n<E025 3>La seconde... <E049><E003 15><E025 3>je ne puis la consigner sur le papier. »");
                R(ref s, "‘I have confessed my sins to my wife.<E049><E003 12>\r\n<E025 3>May she find resolution in my death.’", "« J'ai confessé mes péchés à ma tendre épouse.<E049><E003 12>\r\n<E025 3>Puisse-t-elle trouver l'apaisement dans ma mort. »");
                R(ref s, "‘With my eternal gratitude to my Japanese friend,<E049><E003 10> <E025 3>I rest\r\nmy quill.’", "« Avec mon éternelle gratitude à mon ami japonais,<E049><E003 10> <E025 3>je pose\r\nma plume pour toujours. »");
                R(ref s, "‘Klint van Zieks’", "« Klint Van Peers »");
                return s;
            };

