            // [141] BB\script\output\_sce04_c404_0040_eng#4
            entryTranslators[@"BB\script\output\_sce04_c404_0040_eng#4"] = (s) => {
                R(ref s, "Klint...", "Klint...");
                R(ref s, "Mael Stronghart...", "Mael Stronghart...");
                R(ref s, "...you colluded with Seishiro Jigoku in a criminal plot so\r\nimmense, <E049><E003 8><E025 2>it spanned the oceans.", "...vous avez comploté avec Seishiro Jigoku dans une machination criminelle\r\nsi tentaculaire, <E049><E003 8><E025 2>qu'elle s'étendait au-delà des mers.");
                R(ref s, "And you cold-heartedly murdered all those who knew\r\nthe truth about what happened ten years ago.", "Et vous avez froidement fait abattre tous ceux qui détenaient\r\nla vérité sur les faits survenus il y a dix ans.");
                R(ref s, "But why did you set about that now, <E049><E003 8><E025 3>a whole decade\r\nlater?", "Mais pourquoi avoir déclenché ces purges aujourd'hui, <E049><E003 8><E025 3>une décennie\r\nplus tard ?");
                R(ref s, "To ascend to the very peak.", "Pour gravir l'ultime échelon.");
                R(ref s, "These last ten years made me realise:", "Ces dix années écoulées m'ont fait comprendre une chose :");
                R(ref s, "Being the Lord Chief Justice wasn't enough.<E049><E003 12>\r\n<E025 3><E341>Short of becoming Her Majesty's Attorney General...", "Être Lord juge en chef ne suffisait plus.<E049><E003 12>\r\n<E025 3><E341>Sans la charge suprême de procureur général de Sa Majesté...");
                R(ref s, "...I could have no real power to effect the changes needed\r\nin this country.", "...je ne disposais d'aucun pouvoir réel pour transformer\r\nce pays selon mes desseins.");
                R(ref s, "And for that promotion...<E049><E003 13><E338><E341><E025 3>I needed to ensure no ‘remnants’\r\nof the past remained.", "Et pour décrocher cette promotion... <E049><E003 13><E338><E341><E025 3>je devais m'assurer qu'aucun\r\n« vestige » du passé ne subsistât.");
                R(ref s, "How could you...?", "Comment avez-vous pu... ?");
                R(ref s, "I like everything to run smoothly, <E049><E003 8>in the exact manner\r\nthat I prescribe.<E049><E003 10> Like a well-oiled machine.", "J'aime que tout fonctionne sans accroc, <E049><E003 8>selon les règles précises\r\nque j'édicte.<E049><E003 10> Comme les rouages bien huilés d'une horloge.");
                R(ref s, "And I was just a step away...", "Et je touchais enfin au but...");
                R(ref s, "And for your ambition to succeed...", "Et pour assouvir votre soif d'ambition...");
                R(ref s, "...did you even bother to count the number of brilliant\r\npeople you had killed?!", "...avez-vous seulement pris la peine de compter les êtres brillants\r\nque vous avez froidement sacrifiés ?!");
                R(ref s, "Ah, <E171 1 16 0 10 1><E171 9 17 1 1 2><E049><E003 10>Mr Reaper, <E049><E003 10>are you not forgetting something?", "Ah, <E171 1 16 0 10 1><E171 9 17 1 1 2><E049><E003 10>Messire le Faucheur, <E049><E003 10>n'oublieriez-vous point un détail ?");
                R(ref s, "Such as...?", "Du genre... ?");
                R(ref s, "You've very much adopted your usual prosecutor-like\r\ndemeanour in the proceedings now.", "Vous avez repris avec force votre superbe posture de procureur\r\ndans ces débats.");
                R(ref s, "But the reality of the situation <E049><E003 10>is that you are <E006>the\r\ndefendant<E005> in this trial.", "Mais la réalité des faits <E049><E003 10>est que vous êtes <E006>l'accusé<E005>\r\ndans ce procès.");
                R(ref s, "Ah...", "Ah...");
                R(ref s, "However, <E049><E003 10><E025 2>the presiding judge would appear to have fallen\r\nfrom the bench, <E049><E003 6>as it were.", "Toutefois, <E049><E003 10><E025 2>il semblerait que le président du tribunal\r\nvienne de choir de son estrade, si j'ose dire.");
                R(ref s, "May I suggest, <E003 8>therefore, <E003 8>that we entrust the final\r\nadjudication to an old friend?", "Puis-je suggérer, <E003 8>dès lors, <E003 8>que nous confiions le verdict final\r\nà un vieil ami ?");
                R(ref s, "M-<E049><E003 8><E025 2><E338><E342>My Lord!", "V-<E049><E003 8><E025 2><E338><E342>Votre Honneur !");
                R(ref s, "As a member of the judiciary, <E049><E003 8>I have been following the\r\nproceedings from the gallery.", "En tant que membre de la magistrature, <E049><E003 8>j'ai suivi attentivement\r\nles débats depuis la galerie.");
                R(ref s, "And I must say...<E049><E003 12><E145 15 2><E118 15 1.3><E003 15><E025 3><E239><E092 7>I shan't ever forget the extraordinary\r\nbattle between good and evil<E049><E003 8> that I witnessed here today.", "Et je dois confesser...<E049><E003 12><E145 15 2><E118 15 1.3><E003 15><E025 3><E239><E092 7>que je n'oublierai jamais l'extraordinaire\r\nlutte entre le bien et le mal<E049><E003 8> dont j'ai été le témoin aujourd'hui.");
                return s;
            };

            // [142] BB\script\output\_sce04_c404_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c404_0050_eng#2"] = (s) => {
                R(ref s, "The darkness that has blighted justice in our land these\r\npast ten years <E049><E003 8><E025 3><E145 15 0><E144 15>has at last been dispelled.", "Les ténèbres qui souillaient la justice en notre royaume depuis\r\ndix ans <E049><E003 8><E025 3><E145 15 0><E144 15>sont enfin dissipées.");
                R(ref s, "Thanks, <E049><E003 8>in no small part, <E049><E003 10><E025 2>to the efforts of a bright young\r\nstar from the East.", "Grâce, <E049><E003 8>dans une mesure considérable, <E049><E003 10><E025 2>aux efforts d'un brillant jeune\r\navocat venu d'Orient.");
                R(ref s, "Defence Counsel Naruhodo...", "Maître Naruhodo...");
                R(ref s, "Y-<E049><E003 6><E025 1><E145 1 65><E003 4><E335><E342>Yes, <E049><E003 12>My Lord?!", "O-<E049><E003 6><E025 1><E145 1 65><E003 4><E335><E342>Oui, <E049><E003 12>Votre Honneur ?!");
                R(ref s, "On behalf of everyone here present in the Old Bailey,<E049><E145 15 1><E118 15 1.0><E003 12> I\r\ngive you my heartfelt thanks.", "Au nom de tous ceux qui garnissent cette salle d'Old Bailey,<E049><E145 15 1><E118 15 1.0><E003 12> je\r\nvous adresse mes remerciements les plus chaleureux.");
                R(ref s, "You're too kind, My Lord!", "Vous êtes trop bon, Votre Honneur !");
                R(ref s, "The first time I faced you in court, <E049><E003 8>just under a year ago\r\nnow...", "La première fois que je vous ai affronté au prétoire, <E049><E003 8>il y a un peu\r\nmoins d'un an...");
                R(ref s, "...I had the faintest of intimations.", "...j'ai eu comme une discrète intuition.");
                R(ref s, "That if British justice, <E049><E003 8>so warped and twisted over its long\r\nhistory, <E049><E003 8>was finally to know change...", "Que si la justice britannique, <E049><E003 8>si corrompue et dévoyée au fil de sa longue\r\nhistoire, <E049><E003 8>devait enfin connaître le salut...");
                R(ref s, "...this might just be the man to do it.", "...cet homme pourrait bien être celui qui l'accomplirait.");
                R(ref s, "Wha...?", "Pardon... ?");
                R(ref s, "But at the time, <E049><E003 10><E025 2>I wouldn't allow myself to acknowledge\r\nthe possibility.", "Mais à l'époque, <E049><E003 10><E025 2>je me refusais à concevoir pareille éventualité.");
                R(ref s, "I couldn't overcome my hatred of the Japanese, <E049><E003 10><E145 18 12><E118 18 0.4><E003 10>after the\r\ncircumstances of my brother's death.", "Je ne pouvais surmonter ma haine des Japonais, <E049><E003 10><E145 18 12><E118 18 0.4><E003 10>après la tragédie\r\nde la mort de mon frère.");
                R(ref s, "Mr Naruhodo...", "Monsieur Naruhodo...");
                R(ref s, "Allow me to apologise for countless discourtesies on my\r\npart.<E049><E003 10> <E145 18 0><E118 18 1.1><E003 15><E025 3>You are a lawyer of boundless talent.", "Permettez-moi de vous présenter mes excuses pour mes innombrables discourtoisies.<E049><E003 10> <E145 18 0><E118 18 1.1><E003 15><E025 3>Vous êtes un juriste au talent sans limites.");
                R(ref s, "Oh, <E049><E003 10>Lord van Zieks...", "Oh, <E049><E003 10>Lord Van Peers...");
                R(ref s, "When I first arrived in Great Britain...", "Quand j'ai débarqué en Grande-Bretagne...");
                R(ref s, "...I was literally a nobody.<E049><E003 14>\r\n<E025 3>Certainly not a lawyer.", "...je n'étais rigoureusement personne.<E049><E003 14>\r\n<E025 3>Et certainement pas un avocat.");
                R(ref s, "The truth is, <E049><E003 10><E025 2>my fortunes have entirely been made by the\r\nmiraculous people I've met.", "En réalité, <E049><E003 10><E025 2>mon destin tout entier a été forgé par les personnes\r\nextraordinaires que j'ai rencontrées.");
                R(ref s, "My best friend, <E003 8>Kazuma Asogi, <E003 12><E025 2>who led me here to Britain\r\nin the first place...", "Mon meilleur ami, <E003 8>Kazuma Asogi, <E003 12><E025 2>qui m'a guidé ici en Grande-Bretagne\r\npour commencer...");
                R(ref s, "My loyal and ever-patient judicial assistant, <E003 8><E025 3>Miss Susato,<E003 12>\r\n<E025 2>who helped me study to become a lawyer...", "Ma loyale et dévouée assistante juridique, <E003 8><E025 3>Mademoiselle Susato,<E003 12>\r\n<E025 2>qui m'a soutenu sans relâche dans mes études...");
                R(ref s, "The brilliant Lord van Zieks, <E003 12><E025 2>who never failed to\r\nchallenge his ‘Nipponese’ rival.", "L'illustre Lord Van Peers, <E003 12><E025 2>qui n'a jamais manqué d'éprouver\r\nson rival « nippon ».");
                R(ref s, "And not to <E145 18 0>mention...", "Et sans oublier...");
                R(ref s, "...the exceptional master of logic and reasoning, <E003 8>who\r\nshowed me the true art of deduction...<E003 12><E025 3>Mr Sholmes.", "...l'incomparable maître de la déduction et de la logique, <E003 8>qui\r\nm'a enseigné l'art subtil du raisonnement... <E003 12><E025 3>Monsieur Sholmes.");
                R(ref s, "Saving the best for last, <E049><E003 8>Mr Naruhodo?<E049><E003 10>\r\n<E025 2><E164 2 79 1 2 6 0 0 1><E118 2 1.1><E139 2>...What a relief.", "Garder le meilleur pour la fin, <E049><E003 8>Monsieur Naruhodo ?<E049><E003 10>\r\n<E025 2><E164 2 79 1 2 6 0 0 1><E118 2 1.1><E139 2>...Me voilà rassuré.");
                R(ref s, "I'm well aware...<E049><E003 14>that without all these people's help and\r\nsupport, <E049><E003 10>I wouldn't be where I am today.", "J'ai bien conscience... <E049><E003 14>que sans l'aide et le soutien de chacun d'eux,\r\n<E049><E003 10>je ne serais jamais parvenu jusqu'ici aujourd'hui.");
                R(ref s, "The truth is a guiding light <E049><E003 8>that always leads to happiness.", "La vérité est un phare <E049><E003 8>qui guide toujours vers le bonheur.");
                R(ref s, "I've lived by that principle for a long time now.<E049><E003 10><E145 1 13><E003 15>\r\n<E025 3>But actually, <E049><E003 10><E025 2>it's not true.", "J'ai longtemps vécu en tenant cette maxime pour vraie.<E049><E003 10><E145 1 13><E003 15>\r\n<E025 3>Mais en vérité, <E049><E003 10><E025 2>il n'en est rien.");
                R(ref s, "The truth can also cause great pain.<E049><E003 12> <E025 3>Sometimes even\r\nleave people on the brink of despair.", "La vérité peut aussi infliger des tourments indicibles.<E049><E003 12> <E025 3>Elle peut parfois\r\nplonger les cœurs au bord du désespoir.");
                R(ref s, "And for that reason, <E049><E003 8>there are those who feel the need to\r\nhide the truth.<E049><E003 8> <E145 112 0><E118 112 0.65><E149 112 0 4><E003 10><E025 3>Who do it instinctively, even.", "Et pour cette raison, <E049><E003 8>certains ressentent le besoin impérieux de la masquer.\r\n<E049><E003 8><E145 112 0><E118 112 0.65><E149 112 0 4><E003 10><E025 3>Parfois même d'instinct.");
                R(ref s, "But as soon as we allow our eyes to settle on something\r\nother than the truth...<E049><E003 12><E025 3>the darkness takes hold.", "Mais dès lors que nous détournons nos regards de la vérité,\r\n<E049><E003 12><E025 3>les ténèbres gagnent du terrain.");
                R(ref s, "And from there it grows, <E049><E003 8>until eventually...<E003 10><E025 2>it makes us\r\nblind to the guiding light of the truth altogether.", "Et elles s'étendent, <E049><E003 8>jusqu'à ce que... <E003 10><E025 2>nous soyons rendus aveugles\r\nà la lumière bienfaisante de la vérité.");
                R(ref s, "So that's why it's my belief...", "C'est pourquoi j'ai l'intime conviction...");
                R(ref s, "...that we must all resolve never to avert our eyes from\r\nwhat is just and true.", "...que nous devons tous faire le serment de ne jamais fuir\r\nce qui est juste et véritable.");
                R(ref s, "So that we can continue to walk the straight and narrow\r\npath ahead.", "Afin que nous puissions avancer d'un pas ferme sur le droit\r\nchemin.");
                R(ref s, "Well, <E049><E003 8>I must excuse myself now.", "Bien, <E049><E003 8>je dois désormais prendre congé.");
                R(ref s, "But before I go, <E049><E003 10>Mr Naruhodo, <E049><E003 10><E025 3>let me compliment you on\r\nyour grand opus.", "Mais avant de partir, <E049><E003 10>Monsieur Naruhodo, <E049><E003 10><E025 3>laissez-moi vous féliciter\r\npour votre grand œuvre.");
                R(ref s, "Wha...?!", "Plaît-il... ?!");
                R(ref s, "Without your beautifully composed case against Lord\r\nStronghart, <E049><E003 8><E025 3>Her Majesty would have been unable to act.", "Sans votre magistrale démonstration contre Lord\r\nStronghart, <E049><E003 8><E025 3>Sa Majesté n'aurait jamais pu intervenir.");
                R(ref s, "Thanks to you and your fellows, <E049><E003 6><E164 2 81 1 2 8 0 2 1><E118 2 1.2><E139 2><E025 1>the haunting undertones\r\ncorrupting Britain's justice system have been silenced!", "Grâce à vous et à vos compagnons, <E049><E003 6><E164 2 81 1 2 8 0 2 1><E118 2 1.2><E139 2><E025 1>le funeste murmure\r\nqui corrompait la justice britannique est à jamais réduit au silence !");
                R(ref s, "Erm...", "Euh...");
                R(ref s, "Thank you very much!", "Merci infiniment !");
                R(ref s, "So...<E049><E003 14><E025 1>until our paths cross again somewhere!", "Alors... <E049><E003 14><E025 1>au plaisir de nous croiser à nouveau un jour !");
                R(ref s, "Well then...", "Bien alors...");
                R(ref s, "...it would appear that this long trial has finally come to an\r\nend.", "...il semblerait que ce long procès touche enfin à son dénouement.");
                R(ref s, "My apologies for any anxiety caused, <E049><E003 8>My Lord.", "Toutes mes excuses pour l'émoi suscité, <E049><E003 8>Votre Honneur.");
                R(ref s, "I'm quite sure we shall meet again here in the courtroom\r\nbefore long, <E049><E003 8><E145 15 7><E025 3>Prosecutor Barok van Zieks.", "Je ne doute point que nous nous retrouverons céans sous peu,\r\n<E049><E003 8><E145 15 7><E025 3>Monsieur le procureur Barok Van Peers.");
                R(ref s, "In conclusion of these proceedings, <E049><E003 10>I hereby declare the\r\ndefendant, <E049><E003 8>Barok van Zieks...", "Pour clore définitivement ces débats, <E049><E003 10>je déclare l'accusé,\r\n<E049><E003 8>Barok Van Peers...");
                R(ref s, "That is all.<E049><E003 10><E145 15 0><E003 6>\r\n<E025 1><E346>Court is adjourned!", "C'est tout.<E049><E003 10><E145 15 0><E003 6>\r\n<E025 1><E346>La séance est levée !");
                return s;
            };

        }
